import{L as e,b as t,x as n}from"./vue-Vea_iehr.js";import{oi as r}from"./common-CbCV25qh.js";var i=JSON.parse(`{"path":"/os/dsm/o502gujg/","title":"Web 服务解除默认端口占用 | DSM","lang":"zh-CN","frontmatter":{"title":"Web 服务解除默认端口占用","createTime":"2026/08/27 08:41:38","permalink":"/os/dsm/o502gujg/"},"readingTime":{"minutes":1.63,"words":488},"git":{},"filePathRelative":"os/dsm/002.synology-dsm72-unbind-80-443.md","headers":[]}`),a={name:`002.synology-dsm72-unbind-80-443.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>Synology DSM 7.2 的 Web 服务默认占用 80/443 端口。若需在群晖上部署其他依赖这两个端口的服务（如反向代理、自有 Web 服务器），需先释放端口。本文通过修改 nginx 的模板文件（<code>.mustache</code>）中的端口号，将 DSM 的 Web 端口改为 12080/12443，从而让出 80/443。</p><p>参考来源：<a href="https://www.cnblogs.com/zhengdaojie/p/16019318.html" target="_blank" rel="noopener noreferrer">群晖解除默认的 80/443 端口占用</a></p><h2 id="一、开启-ssh-与-root-权限" tabindex="-1"><a class="header-anchor" href="#一、开启-ssh-与-root-权限"><span>一、开启 SSH 与 root 权限</span></a></h2><ol><li><p>在 DSM 控制面板开启 SSH：</p><p><code>控制面板</code> → <code>终端机和 SNMP</code> → <code>终端机</code> → <code>启动 SSH 功能</code>（默认端口 22）。</p></li><li><p>用 PuTTY 等工具 SSH 登录，并提权为 root：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span></span></code></pre></div><p>登录回显示例：</p><div class="language-text" data-highlighter="shiki" data-ext="text" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-text"><span class="line"><span>login as: qh</span></span>
<span class="line"><span>qh@10.0.0.6&#39;s password:</span></span>
<span class="line"><span>qh@DS918:/$ sudo -i</span></span>
<span class="line"><span>Password:</span></span>
<span class="line"><span>root@DS918:~#</span></span></code></pre></div></li></ol><h2 id="二、修改-nginx-模板端口" tabindex="-1"><a class="header-anchor" href="#二、修改-nginx-模板端口"><span>二、修改 nginx 模板端口</span></a></h2><ol><li><p>放宽模板文件权限以便编辑（修改后务必还原）：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0777</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/syno/share/nginx/server.mustache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0777</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/syno/share/nginx/DSM.mustache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0777</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/syno/share/nginx/WWWService.mustache</span></span></code></pre></div><div class="hint-container warning"><p class="hint-container-title">警告</p><p><code>0777</code> 意味着任意用户可读写执行，属临时放宽权限，仅用于编辑期间。操作完成后必须按本节第 3 步还原为 <code>0644</code>，切勿长期保留 <code>0777</code>。</p></div></li><li><p>用 WinSCP（或 SCP）将以下三个文件下载到本地，把其中的 <code>80</code> 和 <code>443</code> 改为 <code>12080</code> 和 <code>12443</code>，再回传覆盖：</p><ul><li><code>/usr/syno/share/nginx/server.mustache</code></li><li><code>/usr/syno/share/nginx/DSM.mustache</code></li><li><code>/usr/syno/share/nginx/WWWService.mustache</code></li></ul></li><li><p>还原文件权限：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/syno/share/nginx/server.mustache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/syno/share/nginx/DSM.mustache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/syno/share/nginx/WWWService.mustache</span></span></code></pre></div></li></ol><h2 id="三、重启-web-服务生效" tabindex="-1"><a class="header-anchor" href="#三、重启-web-服务生效"><span>三、重启 Web 服务生效</span></a></h2><p>修改模板后需重启 Web 服务才能让新端口生效。DSM 7.2 没有直接的「重启 Web」按钮，可用以下任一方式触发：</p><ul><li><code>控制面板</code> → <code>网络</code> → <code>代理服务器</code>，随便改一个端口号保存，再改回原值，系统会借此自动重启 Web 服务。</li><li>直接重启群晖（耗时较长，作为兜底）。</li></ul><div class="hint-container note"><p class="hint-container-title">笔记</p><p>重启后访问 DSM 管理界面需带上新端口，例如 <code>http://10.0.0.6:12080</code> 与 <code>https://10.0.0.6:12443</code>。原 80/443 即释放，可供其他服务使用。</p></div>`,11)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};